shots.draw_js:
clearScene();setBig(null);
setEq("$$V(s_t)\\;\\leftarrow\\;V(s_t)+\\alpha\\big[\\,r_t+\\gamma V(s_{t+1})-V(s_t)\\,\\big]$$","top");
lamps({y:320,gap:340,items:[
  {label:"不必等回合结束",sub:"每步就更新",state:"on"},
  {label:"不需要回合制",sub:"永不终止也能跑",state:"on"}]});
setCap("TD 每一步都更新。放到同一条轨迹上（α=1）：<b>一个回合能学到多少？</b>");

clearScene();setEq(null);
setBig("TD 每步都更新","所以同样的数据上它学得更快");
setCap("「更新更频繁」是事实。但<b>更新次数</b>和<b>每次的信息量</b>是两个量 —— TD 赢前者，输后者。");

clearScene();setBig(null);
setEq("$$\\alpha=1,\\quad V\\text{ 初始全 }0:\\quad \\text{四笔更新的结果}$$","top");
fillBars({vals:[0,0,0,1],order:[0,1,2,3],step:400,
  x:380,y:420,w:520,h:160,max:1.2,
  label:function(i){return ["①s₃","②s₂","③s₂","④s₁"][i];},
  cls:function(i){return i===3?"g":"r";},
  fmt:function(v){return v.toFixed(0);}});
note("前三笔目标里 V(s′) 全是 0",640,462,"r");
setCap("四笔更新，<b>只有最后一笔碰到奖励</b> —— 而那时前三个状态已经更新完了。");

clearScene();setBig(null);
setEq("$$\\text{同一条轨迹，一个回合之后}$$","top");
fillBars({vals:[1,0,0,0,0,0,0],order:[0,1,2,3,4,5,6],step:260,
  x:210,y:430,w:860,h:170,max:1.2,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i===0?"g":"";},
  fmt:function(v){return v.toFixed(2);}});
setCap("<b>TD 一个回合只更新了一个状态</b>。对照第三集 MC 那张图：那里三根一起立起来。");

clearScene();setBig(null);
setEq("$$\\text{第 2 个回合} \\;\\longrightarrow\\; \\text{第 3 个回合（同一条轨迹反复跑）}$$","top");
morphBars({from:[1,1,0,0,0,0,0],to:[1,1,1,0,0,0,0],
  x:210,y:430,w:860,h:170,max:1.2,dur:1500,
  label:function(i){return "s"+(i+1);},
  cls:function(i){return i===2?"y":"g";},
  fmt:function(v){return v.toFixed(2);}});
setCap("信息<b>每个回合往回走一格</b>。所需回合数与状态到奖励的距离同阶。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"真优势",sub:"在线 · 低方差",state:"on"},
  {label:"真代价",sub:"有偏 · 一回合一格",state:"dead"}]});
note("「1 后面全是 0」只在 α=1 时",640,420,"y");
setCap("<b>指名反驳</b>：TD 的优势是<b>在线、低方差、不需回合制</b> —— 不是「更快」。");

clearScene();setBig(null);
setEq("$$\\delta_t \\;=\\; r_t+\\gamma V(s_{t+1})-V(s_t)$$","top");
note("TD 更新的全部内容",640,330,"sm lg");
note("收敛后它会趋于 0 吗",640,390,"y lg");
setCap("TD 误差<b>不会</b>趋于零。这不是没收敛 —— 是它的定义决定的。");

clearScene();setEq(null);
setBig("δ 学好了就该趋于 0","所以可以拿 |δ| 当收敛判据");
setCap("梯度残差比的是<b>预测与标签</b>；δ 比的是<b>期望与它的一个样本</b>。后者不会消失。");

clearScene();setBig(null);
setEq("$$r=0,\\quad \\gamma=1,\\quad V(s'_1)=0,\\quad V(s'_2)=10,\\quad V(s)=5$$","top");
mdpChain({n:3,y:330,r:32,x:420,gap:220,
  label:function(i){return ["s","s′₁","s′₂"][i];},
  cls:function(i){return i===0?"b":"g";},
  arcs:[[0,1,"0.5","",0]]});
setCap("一个<b>已经完全收敛</b>的例子：V(s)=5 是精确值，没有任何估计误差。");

clearScene();setBig(null);
setEq("$$\\delta = 0 + V(s') - 5 \\;=\\; \\begin{cases}-5 & \\text{抽到 } s'_1\\\\ +5 & \\text{抽到 } s'_2\\end{cases}$$","top");
fillBars({vals:[5,5,0],order:[0,1,2],step:700,
  x:330,y:430,w:620,h:170,max:6,
  label:function(i){return ["抽到 s′₁","抽到 s′₂","δ 的期望"][i];},
  cls:function(i){return i===2?"g":"r";},
  fmt:function(v){return v.toFixed(1);}});
setCap("完全收敛之后，<b>每一次的 |δ| 仍然是 5</b>。归零的只有期望。");

clearScene();setBig(null);
setEq("$$\\sum_t \\alpha_t=\\infty,\\qquad \\sum_t \\alpha_t^2<\\infty$$","top");
lamps({y:320,gap:340,items:[
  {label:"和发散",sub:"才走得到任何地方",state:"on"},
  {label:"平方和收敛",sub:"才压得住噪声",state:"on"}]});
setCap("δ 不归零，所以收敛必须靠 <b>α 趋于 0</b>。α=1/t 同时满足两条；<b>常数 α 只满足第一条</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:300,items:[
  {label:"E[δ] → 0",sub:"成立",state:"on"},
  {label:"δ → 0",sub:"随机环境下不成立",state:"dead"},
  {label:"拿 |δ| 当判据",sub:"永远显示没收敛",state:"dead"}]});
setCap("<b>指名反驳</b>：该监控的是 δ 的<b>移动平均</b>或 V 本身的变化量，不是单次 δ。");

clearScene();setBig(null);
setEq("$$\\text{8 条回合}:\\quad A\\!\\to\\!0\\!\\to\\!B\\!\\to\\!0 \\;(\\times 1),\\qquad B\\!\\to\\!1\\;(\\times 6),\\qquad B\\!\\to\\!0\\;(\\times 1)$$","top");
note("B 访问 8 次，6 次得 1",640,330,"g lg");
note("V(B)=0.75 两法一致",640,390,"g lg");
setCap("固定数据集，γ=1。V(B) 无争议。<b>那 V(A) 等于多少？</b>");

clearScene();setEq(null);
setBig("同一份数据该有唯一答案","两个正确的算法顶多精度不同");
setCap("背后是一个更深的假设：<b>数据里有一个唯一的正确答案</b>。而<b>回答问题的是你对数据做的假设</b>。");

clearScene();setBig(null);
setEq("$$\\text{批量 MC：}\\;\\arg\\min_V \\sum_i \\big(G^{(i)}-V(s^{(i)})\\big)^2$$","top");
note("A 只被访问过一次",640,330,"sm lg");
note("那一次的回报是 0",640,390,"r lg");
setCap("<b>批量 MC：V(A) = 0</b>。它只相信实际发生过的回报，<b>完全不用「A 会到 B」这条信息</b>。");

clearScene();setBig(null);
setEq("$$\\hat P(B\\mid A)=1,\\quad \\hat R(A)=0,\\quad \\hat R(B)=0.75\\;\\Longrightarrow\\;V(A)=0+\\gamma\\,V(B)$$","top");
note("先估一个最大似然 MDP",640,330,"sm lg");
note("再在它上面做 DP",640,390,"v lg");
setCap("<b>批量 TD：V(A) = 0.75</b>。它相信从 A <b>一定</b>会走到 B。");

clearScene();setBig(null);
setEq("$$\\text{同一份数据，}\\; V(A)=0 \\;\\text{ 还是 }\\; V(A)=0.75\\;?$$","top");
fillBars({vals:[0,0.75,0.75],order:[0,1,2],step:640,
  x:330,y:430,w:620,h:170,max:1,
  label:function(i){return ["MC 的 V(A)","TD 的 V(A)","两者的 V(B)"][i];},
  cls:function(i){return i===0?"r":(i===1?"v":"g");},
  fmt:function(v){return v.toFixed(2);}});
setCap("<b>MC 给 0，TD 给 0.75。</b>两者都收敛了，都没算错 —— 数据再多也不会让它们合并。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"批量 MC 问",sub:"最贴合见过的回报",state:"on"},
  {label:"批量 TD 问",sub:"最可能的那个 MDP",state:"on"}]});
note("谁对取决于世界，不取决于算法",640,420,"y");
setCap("<b>指名反驳</b>：分歧不在算法，在<b>假设</b>。你的状态是不是真的充分统计量？");
